	private static boolean hasMapResizeConflict(Throwable failure) {
		for (Throwable cause = failure; cause != null; cause = cause.getCause()) {
			if (cause instanceof LmdbSailStore.MapResizeConflictException) {
				return true;
			}
		}
		return false;
	}

