	private static final class SingleUseRows implements Iterable<BindingSet>, Serializable {
		private static final long serialVersionUID = 1L;
		private final List<BindingSet> rows;
		private int index;
		private int opens;

		private SingleUseRows(List<BindingSet> rows) {
			this.rows = rows;
		}

		@Override
		public Iterator<BindingSet> iterator() {
			opens++;
			return new Iterator<>() {
				@Override
				public boolean hasNext() {
					return index < rows.size();
				}

				@Override
				public BindingSet next() {
					if (!hasNext()) {
						throw new NoSuchElementException();
					}
					return rows.get(index++);
				}
			};
		}

		@Override
		public boolean equals(Object other) {
			return other instanceof SingleUseRows source && rows.equals(source.rows) && index == source.index;
		}

		@Override
		public int hashCode() {
			return 31 * rows.hashCode() + index;
		}
	}

	private static final class BarrierFunction implements Function {
		private final CountDownLatch entered = new CountDownLatch(1);
		private final CountDownLatch release = new CountDownLatch(1);
		private final AtomicInteger calls = new AtomicInteger();

		@Override
		public String getURI() {
			return "urn:binding-replay:sort";
		}

		@Override
		public Value evaluate(ValueFactory factory, Value... args) {
			return args[0];
		}

		@Override
		public Value evaluate(TripleSource source, Value... args) {
			if (calls.incrementAndGet() == 1) {
				try (CloseableIteration<? extends Statement> statements = source.getStatements(null,
						VF.createIRI("urn:binding-replay:predicate"), null)) {
					assertTrue(statements.hasNext());
					entered.countDown();
					assertTrue(release.await(15, TimeUnit.SECONDS), "comparison must be released");
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new AssertionError(interrupted);
				}
			}
			return args[0];
		}
	}
